-- 121_restore_deleted_bkmo_drivers.sql
-- Restores drivers 79 (HERMANUS CASUAL), 88 (EDDIE CASUAL), 97 (JONAS CASUAL)
-- hard-deleted from Bokamosho on 2026-07-27 06:09 UTC (audit 24799-24801).
-- Source: restored pre-deletion snapshot (project xuahjgavltoqjcdamrly, 2026-07-24 14:44 UTC).
-- Rows are reinserted at their ORIGINAL ids; all ids verified vacant in production.
BEGIN;

-- drivers: 3 row(s)

-- driver_pay_cycles: 7 row(s)

-- casual_truck_assignments: 1 row(s)

-- driver_food_payments: 10 row(s)

-- driver_trip_logs: 9 row(s)

-- driver_additional_loads: nothing to restore

-- Re-link the surviving truck loads that were orphaned by ON DELETE SET NULL
UPDATE truck_loads SET driver_id = 88 WHERE id IN (54, 55);
UPDATE truck_loads SET driver_id = 79 WHERE id IN (1375, 1654);
UPDATE truck_loads SET driver_id = 97 WHERE id IN (1373, 1374);

-- Re-link the split-load driver lines (slot 1 on three June split loads)
UPDATE truck_load_driver_splits SET driver_id = 79 WHERE id IN (30, 32, 36);

-- Keep sequences ahead of the reinserted ids
SELECT setval('drivers_id_seq',                  GREATEST((SELECT last_value FROM drivers_id_seq),                  (SELECT MAX(id) FROM drivers)));
SELECT setval('driver_pay_cycles_id_seq',        GREATEST((SELECT last_value FROM driver_pay_cycles_id_seq),        (SELECT MAX(id) FROM driver_pay_cycles)));
SELECT setval('driver_food_payments_id_seq',     GREATEST((SELECT last_value FROM driver_food_payments_id_seq),     (SELECT MAX(id) FROM driver_food_payments)));
SELECT setval('driver_trip_logs_id_seq',         GREATEST((SELECT last_value FROM driver_trip_logs_id_seq),         (SELECT MAX(id) FROM driver_trip_logs)));
SELECT setval('casual_truck_assignments_id_seq', GREATEST((SELECT last_value FROM casual_truck_assignments_id_seq), (SELECT MAX(id) FROM casual_truck_assignments)));

COMMIT;
